entries[1219772] = { ["name"] = "Soul of the Scoundrel", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Scoundrel:\n\nIncreases Mutilate and Saber Slash damage by 20%." }
entries[1219773] = { ["name"] = "Soul of the Thrill Seeker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Thrill Seeker:\n\nReduces the cooldown on Adrenaline Rush by 4 min." }
entries[1219774] = { ["name"] = "Soul of the Shiv Savant", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Shiv Savant:\n\nIncreases your chance to get a critical strike with Daggers by 5%." }
entries[1219775] = { ["name"] = "Soul of the Stalker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Stalker:\n\nIncreases the critical strike chance of your Ambush ability by 30%." }
entries[1219776] = { ["name"] = "Soul of the Efficient", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Efficient:\n\nYour finishing moves cost 50% less Energy." }
entries[1219777] = { ["name"] = "Soul of the Knife Juggler", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Knife Juggler:\n\nWhile Just a Flesh Wound and Blade Dance are active, Crimson Tempest, Blunderbuss, and Fan of Knives cost 20 less Energy and generate 100% increased threat." }
