entries[1219779] = { ["name"] = "Soul of the Equilibrist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Equilibrist:\n\nYour finishing moves have a 20% chance per combo point to make you take 50% less Physical damage from the next melee attack that hits you within 10 sec." }
entries[1219780] = { ["name"] = "Soul of the Poised Brawler", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Poised Brawler:\n\nYour Rolling with the Punches now also activates every time you gain a combo point." }
entries[1219781] = { ["name"] = "Soul of the Black Belt", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Black Belt:\n\nYour Rolling with the Punches also grants you 20% increased Armor from items per stack (capped at 100%)." }
entries[1219782] = { ["name"] = "Soul of the Fencer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Fencer:\n\nThe cooldown on your Main Gauche resets every time your target Dodges or Parries." }
entries[1219783] = { ["name"] = "Soul of the Swashbuckler", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Swashbuckler:\n\nYour Main Gauche now strikes 1 additional nearby target and also causes your Sinister Strike to strike 1 additional nearby target for 10 sec. These additional strikes are not duplicated by Blade Flurry." }
entries[1219784] = { ["name"] = "Soul of the Bloodthirsty", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Bloodthirsty:\n\nWhile active, your Main Gauche also causes you to heal for 15% of all damage done by Sinister Strike. Any excess healing becomes a Blood Barrier, absorbing damage up to 20% of your maximum health." }
entries[1219785] = { ["name"] = "Soul of the Transfusionist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Transfusionist:\n\nLifetap generates 50% more mana and 100% less threat." }
entries[1219786] = { ["name"] = "Soul of the Refined", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[1219787] = { ["name"] = "Soul of the Decimator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Decimator:\n\nYour Nightfall talent has a 4% increased chance to trigger. Your Incinerate has a 4% chance to trigger your Decimation regardless of the target's health." }
entries[1219788] = { ["name"] = "Soul of the Rotbringer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Rotbringer:\n\nIncreases the damage of your periodic spells and Felguard pet by 10 + (5 * Combo Points)%." }
entries[1219789] = { ["name"] = "Soul of the Malevolent", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Malevolent:\n\nPeriodic damage from your Shadowflame, Unstable Affliction, and Curse of Agony spells and damage done by your Felguard have a 4% chance to grant the Shadow Trance effect." }
entries[1219790] = { ["name"] = "Soul of the Shadowmancer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Shadowmancer:\n\nShadowbolt deals 10 + (5 * Combo Points)% increased damage for each of your effects afflicting the target, up to a maximum of 30 + (5 * Combo Points)%." }
entries[1219791] = { ["name"] = "Soul of the Chaos Harbinger", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Chaos Harbinger:\n\nReduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges)." }
entries[1219792] = { ["name"] = "Soul of the Arsonist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Arsonist:\n\nEach time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times." }
entries[1219793] = { ["name"] = "Soul of the Infernal Shepherd", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Infernal Shepherd:\n\nIncreases the Attack Power and Spell Damage your Demon pet gains from your attributes by 20%." }
entries[1219794] = { ["name"] = "Soul of the Demonlord", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Demonlord:\n\nIncreases the benefits of your Master Demonologist talent by 50%." }
entries[1219795] = { ["name"] = "Soul of the Demonic Exorcist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Demonic Exorcist:\n\nBanish is now instant cast, and can be cast on yourself while you are a Demon. You cannot Banish yourself while you have Forbearance, and doing so will give you Forbearance for 1 min." }
entries[1219796] = { ["name"] = "Soul of the Pained", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Pained:\n\nEach time you take damage, you and your pet gain mana equal to the damage taken, up to a maximum of 420 mana per event. Can only occur once every few seconds." }
entries[1219797] = { ["name"] = "Soul of the Flamewraith", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Flamewraith:\n\nYour Shadow Cleave hits have a 20% chance to grant you a Soul Shard, reset the cooldown on Soul Fire, and make your next Soul Fire within 10 sec instant." }
entries[1219798] = { ["name"] = "Soul of the Fleshfeaster", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Fleshfeaster:\n\nWhile you are targeting an enemy within 30 yards, Life Tap grants you mana at the expense of your target's health but deals 50 + (5 * Combo Points)% reduced damage to them. Mana gained remains unchanged." }
entries[1219799] = { ["name"] = "Soul of the Abyssal", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Abyssal:\n\nWhile Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for 15% of your maximum health when you damage a target with Shadowburn." }
entries[1219800] = { ["name"] = "Soul of the Voidborne", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Voidborne:\n\nAny excess healing you deal to yourself is converted into a shield that absorbs damage. This shield can absorb up to 30 + (5 * Combo Points)% of your maximum health, and stacks from multiple heals." }
entries[1219801] = { ["name"] = "Soul of the Umbral Blade", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Umbral Blade:\n\nReduces the cooldown on your Shadow Cleave by 1.5 sec." }
entries[1219802] = { ["name"] = "Soul of the Ritualist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Ritualist:\n\nThe effects of your Demonic Sacrifice now persist while you have a Demon pet active, as long as you do not resummon the sacrificed pet. You may have only one Demonic Sacrifice effect active at a time." }
entries[1219803] = { ["name"] = "Soul of the Pain Spreader", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Pain Spreader:\n\nFor 6 sec after using Shadowcleave, your Searing Pain strikes 1 additional target within melee range." }
entries[1219804] = { ["name"] = "Soul of the Misleader", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Misleader:\n\nYou generate 100% more threat for 8 sec after using Distracting Shot." }
entries[1219805] = { ["name"] = "Soul of the Preyseeker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Preyseeker:\n\nWhile tracking a creature type, you deal 3% increased damage to that creature type." }
entries[1219806] = { ["name"] = "Soul of the Sharpshooter", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Sharpshooter:\n\nYour next Shot ability within 12 sec after Aimed Shot deals 20% more damage." }
entries[1219807] = { ["name"] = "Soul of the Hazard Harrier", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Hazard Harrier:\n\nYour Aimed Shot deals 20% more damage to targets afflicted by one of your trap effects." }
entries[1219808] = { ["name"] = "Soul of the Alternator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Alternator:\n\nYour damaging Shot abilities deal 10% increased damage if the previous damaging Shot used was different than the current one." }
entries[1219809] = { ["name"] = "Soul of the Toxinologist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Toxinologist:\n\nYour Serpent Sting damage is increased by 25% of your Attack Power over its normal duration." }
entries[1219810] = { ["name"] = "Soul of the Bounty Hunter", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Bounty Hunter:\n\nIncreases Kill Shot's damage against non-player controlled targets by 30%." }
entries[1219811] = { ["name"] = "Soul of the Trick Shooter", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Trick Shooter:\n\nKill Shot's cooldown is reduced by 50%. While Rapid Fire is active with Rapid Killing engraved, Kill Shot has no cooldown, and when used against a non-player controlled target, fires 3 additional Kill Shots at 30% damage, with a minimum range." }
entries[1219812] = { ["name"] = "Soul of the Beast Tender", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Beast Tender:\n\nIncreases the Attack Power your Beast pet gains from your attributes by 20%." }
entries[1219813] = { ["name"] = "Soul of the Hound Master", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Hound Master:\n\nIncreases the Focus regeneration of your Beast pet by 20%." }
entries[1219814] = { ["name"] = "Grasping Spirits" }
entries[1219815] = { ["name"] = "Soul of the Alpha Tamer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Alpha Tamer:\n\nIncreases the Focus regeneration of your pets by 100%." }
entries[1219816] = { ["name"] = "Soul of the Huntsman", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Huntsman:\n\nYour Mongoose Bite also reduces its target's chance to Dodge by 1% and increases your chance to hit by 1% for 30 sec." }
entries[1219818] = { ["name"] = "Soul of the Retaliator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Retaliator:\n\nMongoose Bite also activates for 5 sec whenever your target Parries or Blocks or when your melee attack misses." }
entries[1219819] = { ["name"] = "Soul of Echoes", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of Echoes:\n\nRaptor Strike increases the damage done by your next other melee ability (excluding Wing Clip) within 5 sec by 20%." }
entries[1219820] = { ["name"] = "Soul of the Lethal Lasher", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Lethal Lasher:\n\nIncreases damage dealt by your main hand weapon with Raptor Strike and Wyvern Strike by 20%." }
entries[1219821] = { ["name"] = "Soul of the Kineticist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Kineticist:\n\nYour periodic damage has a 5% chance to reset the cooldown on one of your Strike abilities. The Strike with the longest remaining cooldown is always chosen." }
entries[1219822] = { ["name"] = "Soul of the Strategist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Strategist:\n\nIncreases Wyvern Strike damage over time by 50% and increases your pet's maximum focus by 50." }
entries[1219823] = { ["name"] = "Soul of the Deadly Striker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Deadly Striker:\n\nIncreases the impact damage of Mongoose Bite and all Strikes by 20%." }
entries[1219824] = { ["name"] = "Soul of the Hastened Healer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Hastened Healer:\n\n-0 sec to the casting time of Flash Heal and -0 sec to the casting time of Greater Heal." }
entries[1219825] = { ["name"] = "Soul of the Refined", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[1219826] = { ["name"] = "Soul of the Celebrant", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Celebrant:\n\nIncreases your critical strike chance with Prayer of Healing and Circle of Healing by 25%." }
entries[1219827] = { ["name"] = "Soul of the Faithful", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Faithful:\n\nAllows 15% of your Mana regeneration to continue while casting." }
entries[1219828] = { ["name"] = "Soul of the Serendipitous", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Serendipitous:\n\nYour periodic healing has a 2% chance to make your next spell with a casting time less than 10 seconds an instant cast spell." }
entries[1219829] = { ["name"] = "Soul of the Resonant", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Resonant:\n\nCircle of Healing and Penance also place a heal over time effect on their targets that heals for 25% as much over 15 sec." }
entries[1219830] = { ["name"] = "Soul of the Devotee", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Devotee:\n\nYour Prayer of Mending gains 2 additional charges." }
entries[1219831] = { ["name"] = "Soul of the Archbishop", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Archbishop:\n\nYour Circle of Healing now heals the most injured member of the target party for 100% more." }
entries[1219832] = { ["name"] = "Soul of the Penitent", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Penitent:\n\nReduces the cooldown of your Penance spell by 6 sec." }
entries[1219833] = { ["name"] = "Soul of the Soul Warder", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Soul Warder:\n\nIncreases the damage absorbed by your Power Word: Shield spell by 10%." }
entries[1219834] = { ["name"] = "Soul of the Twilight Walker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Twilight Walker:\n\nYou may cast Flash Heal while in Shadowform." }
entries[1219835] = { ["name"] = "Soul of the Mind Breaker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Mind Breaker:\n\nMind Blast critical strikes reduce the duration of your next Mind Flay by 50% while increasing its total damage by 50%." }
entries[1219836] = { ["name"] = "Soul of the Deathdealer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Deathdealer:\n\nReduces the cooldown of your Shadow Word: Death spell by 6 sec." }
entries[1219837] = { ["name"] = "Soul of the Spirit Font", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Spirit Font:\n\nYour Shadow Word: Pain has a 2.0% chance per talent point in Spirit Tap to trigger your Spirit Tap talent when it deals damage, or a 20% chance per talent point when a target dies with your Shadow Word: Pain active. Inner Focus also has a 20% chance per talent point to trigger Spirit Tap." }
entries[1219838] = { ["name"] = "Soul of the Zealot", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Zealot:\n\nWhile Spirit Tap is active, you deal 25% more Shadow damage." }
entries[1219839] = { ["name"] = "Soul of the Unwavering Defiler", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Unwavering Defiler:\n\nYour Mind Flay no longer loses duration from taking damage and launches a free Mind Spike at the target on cast." }
entries[1219840] = { ["name"] = "Soul of the Contemnor", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Contemnor:\n\nYour Mind Spike is now instant, deals 10% more damage, and can be cast while channeling another spell." }
entries[1219841] = { ["name"] = "Soul of the Plaguebringer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Plaguebringer:\n\nYour Pain and Suffering rune can now refresh the duration of Devouring Plague." }
entries[1219842] = { ["name"] = "Soul of the Reverberant", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Reverberant:\n\nYour Temporal Beacons last 20% longer." }
entries[1219843] = { ["name"] = "Soul of the Chronohealer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Chronohealer:\n\nIncreases all chronomantic healing you deal by 10%." }
entries[1219844] = { ["name"] = "Soul of Temporal Longing", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of Temporal Longing:\n\nEach time you heal a target with Regeneration, the remaining cooldown on Rewind Time is reduced by 1 sec." }
entries[1219845] = { ["name"] = "Soul of the Precognitive", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Precognitive:\n\nYour Arcane Missiles refunds 10% of its base mana cost each time it deals damage." }
entries[1219846] = { ["name"] = "Soul of the Arcanist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Arcanist:\n\nArcane Blast gains a 10% additional chance to trigger Missile Barrage, and Missile Barrage now affects Regeneration the same way it affects Arcane Missiles." }
entries[1219847] = { ["name"] = "Soul of the Eternal Caretaker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Eternal Caretaker:\n\nYour Temporal Beacons caused by Mass Regeneration now last 21 sec." }
entries[1219848] = { ["name"] = "Soul of the Spellbider", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Spellbider:\n\nYour Arcane Blast increases damage done by an additional 10% per stack." }
entries[1219849] = { ["name"] = "Soul of the Wardshaper", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Wardshaper:\n\nYour Mana Shield, Fire Ward, and Frost Ward absorb 50% more damage and also place a Temporal Beacon on the target for 30 sec." }
entries[1219850] = { ["name"] = "Soul of Winter's Grasp", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of Winter's Grasp:\n\nIncreases the chance to trigger your Fingers of Frost rune by an additional 15%." }
entries[1219851] = { ["name"] = "Soul of the Cryomancer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Cryomancer:\n\nIncreases damage done by your Frostbolt and Spellfrost Bolt spells by 65%." }
entries[1219852] = { ["name"] = "Soul of the Evoker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Evoker:\n\nYou are immune to all damage while channeling Evocation." }
entries[1219853] = { ["name"] = "Soul of the Elementalist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Elementalist:\n\nYou gain 1% increased damage for 15 sec each time you cast a spell from a different school of magic." }
entries[1219854] = { ["name"] = "Soul of the Magical Armorer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Magical Armorer:\n\nMage Armor increases your mana regeneration while casting by an additional 15%. Molten Armor increases your spell damage and healing by 18. Ice Armor grants 20% increased chance to trigger Fingers of Frost." }
entries[1219855] = { ["name"] = "Soul of the Kindler", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Kindler:\n\nDecreases the threat generated by your Fire spells by 20%." }
entries[1219856] = { ["name"] = "Soul of Fiery Convergence", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of Fiery Convergence:\n\nYour Pyroblast deals 20% increased damage to targets afflicted with your Fireball's periodic effect." }
entries[1219857] = { ["name"] = "Soul of the Perpetual Blaze", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Perpetual Blaze:\n\nYour Fireball's periodic effect gains increased damage over its duration equal to 100% of its impact damage." }
entries[1219858] = { ["name"] = "Soul of the Pyromaniac", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Pyromaniac:\n\nYour Fire Blast now also causes your next Fire spell to gain 50% increased critical strike chance for 10 sec." }
entries[1219859] = { ["name"] = "Soul of the Igniter", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Igniter:\n\nIncreases the damage done by your Ignite talent by 10%." }
entries[1219860] = { ["name"] = "Soul of the Torcher", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Torcher:\n\nYour Fireball, Frostfire Bolt, and Balefire Bolt spells gain 3% increased damage for each of your Fire effects on your target, up to a maximum increased of 9%." }
entries[1219861] = { ["name"] = "Soul of the Pristine Blocker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Pristine Blocker:\n\nIncreases the block value of your shield by 30." }
entries[1219862] = { ["name"] = "Soul of the Lightwarden", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Lightwarden:\n\nHeal for 189 to 211 when you Block. Can only heal once every few seconds." }
entries[1219863] = { ["name"] = "Soul of the Radiant Defender", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Radiant Defender:\n\nHoly Shield no longer has charges and instead always lasts its full duration. In addition, its damage is increased by 80% of your shield block value." }
entries[1219864] = { ["name"] = "Soul of the Shieldbearer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Shieldbearer:\n\nIncreases the bonus chance to Block from Holy Shield by 10%." }
entries[1219865] = { ["name"] = "Soul of the Bastion", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Bastion:\n\nYou take 10% reduced damage while Holy Shield is active." }
entries[1219866] = { ["name"] = "Soul of the Reckoner", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Reckoner:\n\nYour Reckoning talent now has a 20% chance per talent point to trigger when you Block." }
entries[1219867] = { ["name"] = "Soul of the Ironclad", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Ironclad:\n\nYour Blessing of Sanctuary also grants 10% increase to all stats when cast on yourself." }
entries[1219868] = { ["name"] = "Soul of the Guardian", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Guardian:\n\nShield of the Righteous causes your next Holy Light to be instant cast. If cast on self, it will refund 100% of its mana cost and be unaffected by Guarded by the Light." }
entries[1219869] = { ["name"] = "Soul of the Peacekeeper", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Peacekeeper:\n\nIncreases the chance for allies to trigger your Judgement of Light or Judgement of Wisdom to 70%." }
entries[1219870] = { ["name"] = "Soul of the Refined", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[1219871] = { ["name"] = "Soul of the Exemplar", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Exemplar:\n\nWhenever your Flash of Light, Holy Light, or Beacon of Light heals a target to full health, you also heal all members of their party for 189 to 211 health." }
entries[1219872] = { ["name"] = "Soul of the Inquisitor", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Inquisitor:\n\nIncreases the critical strike chance of Holy Shock by 5%." }
entries[1219873] = { ["name"] = "Soul of the Sovereign", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Sovereign:\n\nIncreases the damage done by your Consecration by 50%." }
entries[1219874] = { ["name"] = "Soul of the Dominus", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Dominus:\n\nWhile you are not your Beacon of Light target, your Beacon of Light target is also healed by 75% of the damage you deal with Consecration, Exorcism, Holy Shock, Holy Wrath, and Hammer of Wrath." }
entries[1219875] = { ["name"] = "Soul of the Vindicator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Vindicator:\n\nReduces the cooldown on Divine Light by 25%." }
entries[1219876] = { ["name"] = "Soul of the Altruist", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Altruist:\n\nYour heals on your Beacon of Light target also heal the nearest friendly injured target for 90% as much." }
entries[1219877] = { ["name"] = "Soul of the Arbiter", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Arbiter:\n\nYour Judgement of Light and Judgement of Wisdom also grant the effects of Judgement of the Crusader." }
entries[1219878] = { ["name"] = "Soul of the Sealbearer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Sealbearer:\n\nYour Seal of Command, Seal of Righteousness, Seal of Martyrdom, and Sunlight deal 35% less damage, but now persist for 6 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active." }
entries[1219879] = { ["name"] = "Soul of the Justicar", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Justicar:\n\nIncreases damage done by your damaging Judgements by 20% and your Judgements no longer consume your Seals on the target. Your Judgements can now trigger multiple Seals if active." }
entries[1219880] = { ["name"] = "Soul of the Judicator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Judicator:\n\nReduces the cooldown on your Judgement ability by 5 sec, but reduces the damage your Judgements deal by 45%." }
entries[1219881] = { ["name"] = "Soul of the Ascendant", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Ascendant:\n\nYour Judgement grants 1% increased Holy damage for 8 sec, stacking up to 5 times." }
entries[1219882] = { ["name"] = "Soul of the Retributor", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Retributor:\n\nIncreases Crusader Strike damage by 50%." }
entries[1219883] = { ["name"] = "Soul of the Excommunicator", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Excommunicator:\n\nYour basic attacks with two-handed melee weapons increase the damage of your next Exorcism cast within 20 sec by 35%. Stacking up to 3 times." }
entries[1219884] = { ["name"] = "Soul of the Lightbringer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Lightbringer:\n\nIncreases damage done by your Holy Shock spell by 50%." }
entries[1219885] = { ["name"] = "Soul of the Exile", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Exile:\n\nReduces the cooldown of your Exorcism spell by 3 sec and increases its damage done by 50%." }
entries[1219886] = { ["name"] = "Soul of the Templar", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Templar:\n\nWhile a one-handed weapon is equipped, Crusader Strike now unleashes the Judgement effect of your Seals, but does not consume the Seal." }
entries[1219887] = { ["name"] = "Soul of the Windwalker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Windwalker:\n\nIncreases your attack speed by 1% for your next 3 swings after you parry, dodge, or block." }
entries[1219888] = { ["name"] = "Soul of the Shield Master", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Shield Master:\n\nYour parries and dodges also activate your Shield Mastery rune ability." }
entries[1219889] = { ["name"] = "Soul of the Totemic Protector", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Totemic Protector:\n\nYour Stoneskin Totem also reduces Physical damage taken by 5% and your Windwall Totem also reduces Magical damage taken by 5%." }
entries[1219890] = { ["name"] = "Soul of the Shock-Absorber", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Shock-Absorber:\n\nYour Flame Shock also grants 30% increased chance to Block for 5 sec or until you Block an attack." }
entries[1219891] = { ["name"] = "Soul of the Spiritual Bulwark", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Spiritual Bulwark:\n\nEach time you Block, your Block amount is increased by 10% of your Spell Damage for 6 sec, stacking up to 3 times." }
entries[1219892] = { ["name"] = "Soul of the Maelstrombringer", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Maelstrombringer:\n\nEach time you Block an attack, you have a 50% chance to trigger your Maelstrom Weapon rune." }
entries[1219893] = { ["name"] = "Soul of the Lavawalker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Lavawalker:\n\nDamaging a target with Stormstrike, Lava Burst, or Molten Blast also reduces all damage you take by 10% for 10 sec." }
entries[1219894] = { ["name"] = "Soul of the True Alpha", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the True Alpha:\n\nWhen your Spirit of the Alpha is cast on yourself, it also increases your health by 10%, your threat generated by 20%, and all damage you deal by 10%." }
entries[1219895] = { ["name"] = "Soul of the Totemkeeper", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Totemkeeper:\n\nThe radius of your totems that affect friendly targets is increased to 40 yd." }
entries[1219896] = { ["name"] = "Soul of the Ancestors", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Ancestors:\n\nAfter casting your Healing Wave, Lesser Healing Wave, or Riptide spell, gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell." }
entries[1219897] = { ["name"] = "Soul of the Spiritweaver", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Spiritweaver:\n\nYour Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 60%, and the spell will jump to up to 2 additional targets." }
entries[1219898] = { ["name"] = "Soul of the Waterwalker", ["text"] = "3 sec cast\nRequires Shoulders\nPermanently imbue your shoulders with the Soul of the Waterwalker:\n\nYour non-periodic damaging and healing critical strikes now have a 100% chance to trigger your Water Shield, but do not consume a charge or trigger its cooldown." }
